function icon(name,cl=''){return `<svg aria-hidden="true" class="ico ${cl}" viewBox="0 0 24 24">${ICONS[name]||ICONS.heart}</svg>`;}
function esc(v){return String(v===null||v===undefined?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
/** Buyer-facing dates follow the browser/device timezone, not the Apps Script manifest timezone.
 * Browser timezone also handles DST automatically. Dates stay YYYY-MM-DD strings in the private Sheet.
 * Event timestamps (createdAt/updatedAt) are stored as UTC instants by the existing backend.
 */
function cmDeviceTimeZone(){
  try { return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; }
  catch(e){ return 'UTC'; }
}
function cmLocalCalendarParts(now = new Date()){
  try {
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: cmDeviceTimeZone(), year: 'numeric', month: '2-digit', day: '2-digit'
    }).formatToParts(now);
    const p = Object.fromEntries(parts.filter(x => x.type !== 'literal').map(x => [x.type,x.value]));
    return {year:p.year,month:p.month,day:p.day};
  } catch(e){
    return {year:String(now.getFullYear()),month:String(now.getMonth()+1).padStart(2,'0'),day:String(now.getDate()).padStart(2,'0')};
  }
}
function today(){const p=cmLocalCalendarParts();return `${p.year}-${p.month}-${p.day}`;}
function cmClockLabel(){
  return new Intl.DateTimeFormat('en-GB', {
    timeZone:cmDeviceTimeZone(), weekday:'short', day:'numeric', month:'short', year:'numeric',
    hour:'2-digit', minute:'2-digit', hour12:true
  }).format(new Date());
}
function dayMs(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date)))return NaN;return Date.UTC(+date.slice(0,4),+date.slice(5,7)-1,+date.slice(8,10));}
function dateAdd(date,days){const n=dayMs(date);return Number.isFinite(n)?new Date(n+days*86400000).toISOString().slice(0,10):'';}
function fmtDate(d){if(!d)return 'Not set';const n=dayMs(d);return Number.isFinite(n)?new Date(n).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):String(d);}
function dateDiff(a,b){return Math.floor((dayMs(a)-dayMs(b))/86400000);}
function parseDateRange(days){return [dateAdd(today(),1-days),today()];}
const state={boot:null,screen:'dashboard',type:'DAILY',search:'',showArchived:false,period:'30',drawer:false,modal:null,
  filterMode:'all',filterExact:today(),filterFrom:dateAdd(today(),-29),filterTo:today(), reportFrom:dateAdd(today(),-29),reportTo:today(),reportTypes:[],careDate:today(),careMonth:today().slice(0,7),careCategory:'all',guideStep:0,guideKey:'dashboard',guideCoach:null,libraryTab:'all',busy:false};
